// ===== p96 : la texture du sol sur toute la carte ; les petits jeux stratégiques texturés ; les fougères partout en forêt ;
// le gibier vivant (le cabri Meshy animé, qui marche, broute, lève la tête au hasard) ; des champs qu'on reconnaît =====

// ----- 1. La grande carte : le grain du sol (texture ambientCG) se mêle aux couleurs du relief -----
{let fait=0;setInterval(()=>{try{if(fait||typeof terr==='undefined'||!terr||!terr.material||!terr.material.uniforms||typeof tx91!=='function')return;const t=tx91('sol',1);t.repeat.set(1,1);terr.material.uniforms.det={value:t};terr.material.uniforms.detOn={value:1};fait=1}catch(e){}},800)}

// ----- 2. Les petits jeux stratégiques : la bataille d'escouades et la carte de la Survie prennent le grain du sol et des feuilles -----
const IMG96={};['sol','feuille','basalte','torchis'].forEach(k=>{const i=new Image();i.src=TEX91[k];IMG96[k]=i});
function motif96(x,k,a,op){const i=IMG96[k];if(!i||!i.complete)return false;const p=x.createPattern(i,'repeat');x.save();x.globalAlpha=a;x.globalCompositeOperation=op||'multiply';x.fillStyle=p;return p}
{const bf=btFond;btFond=function(){const cv=bf.apply(this,arguments);try{const x=cv.getContext('2d');if(motif96(x,'sol',BT.nuit?.3:.5)){x.fillRect(0,0,cv.width,cv.height);x.restore()}
 if(motif96(x,'feuille',BT.nuit?.35:.55)){BT.C.F.forEach(f=>{x.beginPath();x.arc(f.x,f.y,f.r,0,7);x.fill()});x.restore()}
 if(BT.C.rav&&motif96(x,'basalte',.8)){x.fillRect(0,BT.C.rav.y-13,cv.width,26);x.restore()}
 if(BT.C.k==='hab'&&motif96(x,'torchis',.35)){x.fillRect(120,355,260,285);x.fillRect(640,355,260,285);x.restore()}}catch(e){}return cv}}
{const kc=kCarte;kCarte=function(){const r=kc.apply(this,arguments);try{const cv=$('kC');if(!cv)return r;const x=cv.getContext('2d');x.setTransform(1,0,0,1,0,0);if(motif96(x,'sol',.28)){x.fillRect(0,0,cv.width,cv.height);x.restore()}}catch(e){}return r}}

// ----- 3. Vue personnage : des fougères partout en forêt (fanjans arborescents et petites fougères au sol) -----
function vpFougeres(){const V=VP;if(!V||V.foug96)return;V.foug96=1;const t=V.t,n=t.bare?4:t.forest?70:22,nP=t.bare?10:t.forest?220:80,P=[];
 const libre=(x,z)=>Math.hypot(x,z+30)>9&&!V.arb.some(a=>Math.hypot(a.x-x,a.z-z)<a.r+.6);
 for(let i=0;i<n*3&&P.length<n;i++){const x=(Math.random()-.5)*150,z=(Math.random()-.5)*150;if(libre(x,z))P.push({x,z,h:2.2+Math.random()*2.8})}
 const mt=new THREE.MeshLambertMaterial({color:0x4a3a2a}),mf=new THREE.MeshLambertMaterial({color:0x4f8a3a,side:THREE.DoubleSide});try{mf.map=tx91('feuille',1);mt.map=tx91('ecorce',1);mt.color.setHex(0x8a7058)}catch(e){}
 const tr=new THREE.InstancedMesh(new THREE.CylinderGeometry(.09,.13,1,6).translate(0,.5,0),mt,P.length);
 const fg=new THREE.PlaneGeometry(.42,1.6,1,4).translate(0,.8,0);{const pa=fg.attributes.position;for(let i=0;i<pa.count;i++){const y=pa.getY(i),w=1-y/1.6;pa.setX(i,pa.getX(i)*(.35+w*.9));pa.setZ(i,-Math.pow(y/1.6,2)*.55)}fg.computeVertexNormals()}
 const NF=9,fr=new THREE.InstancedMesh(fg,mf,P.length*NF+nP*6),M=new THREE.Matrix4(),Q=new THREE.Quaternion(),E=new THREE.Euler(),Sv=new THREE.Vector3(),Pv=new THREE.Vector3();let k=0;
 P.forEach((p,i)=>{const y=V.h(p.x,p.z);M.compose(Pv.set(p.x,y,p.z),Q.identity(),Sv.set(1,p.h,1));tr.setMatrixAt(i,M);for(let j=0;j<NF;j++){E.set(-.9-Math.random()*.4,j/NF*6.283+Math.random()*.3,0,'YXZ');Q.setFromEuler(E);M.compose(Pv.set(p.x,y+p.h-.05,p.z),Q,Sv.set(1.3,1.3,1.3));fr.setMatrixAt(k++,M)}V.arb.push({x:p.x,z:p.z,r:.25})});
 for(let i=0;i<nP;i++){const x=(Math.random()-.5)*150,z=(Math.random()-.5)*150;if(Math.hypot(x,z+30)<8)continue;const y=V.h(x,z),s=.35+Math.random()*.4;for(let j=0;j<6;j++){E.set(-1.0-Math.random()*.3,j/6*6.283+Math.random()*.4,0,'YXZ');Q.setFromEuler(E);M.compose(Pv.set(x,y,z),Q,Sv.set(s,s,s));fr.setMatrixAt(k++,M)}}
 fr.count=k;tr.instanceMatrix.needsUpdate=fr.instanceMatrix.needsUpdate=true;V.sc.add(tr);V.sc.add(fr)}

// ----- 4. Le gibier vivant : le cabri Meshy animé (marche, broute), qui s'arrête, broute ou lève la tête au hasard -----
function vpCabris(){const V=VP;if(!V||V.cab96)return;if(typeof CABA==='undefined')return(V.cab96=1);if(!CABA.buf){if(CABA.buf!==false&&typeof cabCharger==='function')cabCharger();return}V.cab96=1;
 V.an.forEach(a=>{new THREE.GLTFLoader().parse(CABA.buf.slice(0),'',g=>{if(VP!==V)return;const r=g.scene;r.traverse(m=>{if(m.isMesh)m.frustumCulled=false});const b=new THREE.Box3().setFromObject(r),h=(b.max.y-b.min.y)||1.68;const w=new THREE.Group();r.rotation.y=Math.PI/2;r.position.y=-b.min.y;w.add(r);w.scale.setScalar(.85/h);
  const mx=new THREE.AnimationMixer(r),A={};g.animations.forEach(c=>{A[c.name]=mx.clipAction(c);A[c.name].play();A[c.name].setEffectiveWeight(0)});if(A.marche)A.marche.setEffectiveWeight(1);
  w.position.copy(a.m.position);w.rotation.copy(a.m.rotation);V.sc.remove(a.m);V.sc.add(w);a.m=w;a.mx=mx;a.A=A;a.px=a.x;a.pz=a.z;a.pause=Math.random()*4;a.tete=0},()=>{})})}
{const vb=vpBoucle;let last=performance.now();vpBoucle=function(){const now=performance.now(),dt=Math.min(.1,(now-last)/1000);last=now;const V=VP;
 // au hasard, un cabri tranquille s'arrête pour brouter : on le retient sur place
 const hold=V&&V.an?V.an.filter(a=>a.mx&&!a.mort&&a.et==='calme'&&a.pause>0).map(a=>[a,a.x,a.z]):[];
 vb.apply(this,arguments);try{if(!VP||!VP.p84)return;if(!VP.foug96)vpFougeres();if(!VP.cab96)vpCabris();
  hold.forEach(([a,x,z])=>{if(a.et==='calme'){a.x=x;a.z=z;a.m.position.x=x;a.m.position.z=z;a.m.position.y=VP.h(x,z)}});
  VP.an.forEach(a=>{if(!a.mx)return;if(a.mort){a.mx.timeScale=0;return}const v=Math.hypot(a.x-a.px,a.z-a.pz)/Math.max(.001,dt);a.px=a.x;a.pz=a.z;
   if(a.et==='calme'){a.pause-=dt;if(a.pause<-(4+Math.random()*6))a.pause=2+Math.random()*5}
   const br=v<.3?1:0;if(a.A.broute)a.A.broute.setEffectiveWeight(br*(a.pause>0&&Math.sin(VP.tps*.7+a.dir*3)>-.3?1:.15));if(a.A.marche)a.A.marche.setEffectiveWeight(br?0:1);a.mx.timeScale=v>4?1.8:1;a.mx.update(dt)})}catch(e){console.warn(e)}}}

// ----- 5. Des champs qu'on reconnaît : sur l'habitation, des rangs de canne (ou de maïs avant 1715), sillons compris -----
const KC96={"crops_bambooStageB": "", "crops_cornStageC": "", "crops_dirtRow": ""};
(function(){const go=()=>{if(!window.THREE||!THREE.GLTFLoader||typeof KM92==='undefined'){setTimeout(go,900);return}const L=new THREE.GLTFLoader();Object.keys(KC96).forEach(k=>{const b=atob(KC96[k]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);try{L.parse(u.buffer,'',g=>{KM92[k]=g.scene},()=>{})}catch(e){}})};go()})();
{const vb=vpBoucle;vpBoucle=function(){vb.apply(this,arguments);try{const V=VP;if(!V||!V.p84||V.champ96||!S.voieC||(VPLIEU&&VPLIEU.g)||!KM92.crops_bambooStageB||typeof km92Inst!=='function')return;V.champ96=1;
 const k=S.year>=1715?'crops_bambooStageB':'crops_cornStageC',R=[],D=[];for(let r=0;r<7;r++)for(let c=0;c<12;c++){const x=10+c*1.3,z=-50+r*1.6;R.push({x,y:V.h(x,z),z,r:(Math.random()-.5)*.3});if(c%2===0)D.push({x,y:V.h(x,z)-.02,z,r:Math.PI/2})}
 km92Inst(V,k,R,k==='crops_bambooStageB'?2.4:1.6);if(KM92.crops_dirtRow)km92Inst(V,'crops_dirtRow',D,.25);V.arb.push({x:17,z:-45,r:.1});vpMsg(S.year>=1715?'À côté de l’habitation : les rangs de canne.':'À côté de l’habitation : le champ de maïs.')}catch(e){}}}
